INSERT INTO "public"."tasks" ("name", "description", "task_type", "guide_url", "action_url", "required_docs", "output", "step_order", "is_final", "created_at", "updated_at", "next_task_id") VALUES ('Pre-inscripción en el RFC', 'Esta tarea es el primer paso para obtener tu RFC. Deberás realizar la preinscripción en línea y luego finalizar el proceso en una oficina del SAT.', 'ONLINE', 'https://www.sat.gob.mx/consulta/55930/lo-que-necesitas-saber-para-ser-contribuyente', 'https://www.sat.gob.mx/tramites/operacion/82714/realiza-tu-inscripcion-en-el-rfc-persona-fisica', '[]', 'ACUSE DE PREINSCRIPCIÓN AL REGISTRO FEDERAL DE CONTRIBUYENTES', '1', 'false', '2024-10-18 23:24:22.315151+00', '2024-10-18 23:24:22.315151+00', '2'), ('Inscripción en el RFC', 'Finaliza tu inscripción en el RFC una vez hayas terminado el paso anterior en línea.', 'IN_SITE', null, null, '[{"name": "Acuse de pre-inscripción en el RFC", "type": "PDF", "mandatory": true}, {"name": "CURP", "type": "Documento", "context": "Original", "mandatory": true}, {"name": "Comprobante de domicilio", "type": "PDF", "context": "No mayor a tres meses", "mandatory": true}, {"name": "Identificación oficial", "type": "Documento", "context": "Original", "mandatory": true}]', 'Si cumples con los requisitos recibe: "SOLICITUD DE INSCRIPCIÓN AL REGISTRO FEDERAL DE CONTRIBUYENTES y ACUSE ÚNICO DE INSCRIPCIÓN EN EL REGISTRO FEDERAL DE CONTRIBUYENTES."

Si no cumples con algún requisito recibe: "ACUSE DE PRESENTACIÓN INCONCLUSA DE SOLICITUD DE INSCRIPCIÓN O AVISO DE ACTUALIZACIÓN EN EL RFC" Con el motivo por el cual no se concluyó el trámite.', null, 'true', '2024-10-18 23:34:46.068272+00', '2024-10-18 23:34:46.068272+00', null);